"""The load pipeline."""

from data.ingest.reader import read_trades


def guarded(step):
    """Return what step returns."""
    return step()


def run_load(path: str) -> int:
    """Read the trades at path and return their count."""
    rows = guarded(lambda: read_trades(path))
    return len(rows)
